insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam is a state in Northeast India. Its capital is {{term:dispur|Dispur}}, which is part of Guwahati. Assam covers an area of 78,438 square kilometres.$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
