insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$According to Assam at a Glance 2025, the state has 35 districts, 80 {{term:sub-division|sub-divisions}}, 154 {{term:revenue-circle|revenue circles}} and 219 {{term:development-block|development blocks}}.$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$For rural local government there are 27 Zilla Parishads, 183 Anchalik Panchayats and 2,170 Gaon Panchayats.$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h2', 6, 'heading', 'normal', $t$Population (Census 2011)$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 7, 'paragraph', 'normal', $t$The last completed {{term:census}} was held in 2011. These are the main figures for Assam:$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 8, 'list', 'normal', $t$Total population: 3,12,05,576 (males 1,59,39,443; females 1,52,66,133)
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 9, 'paragraph', 'normal', $t$In 2011, Assam had 2.58 percent of India's population.$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 10, 'fact_box', 'exam_fact', $t$Remember for exams: area 78,438 sq km, 35 districts, 126 Assembly seats, 14 Lok Sabha seats, sex ratio 958 and literacy 72.19% (Census 2011).$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$এনেকৈয়ে অসম: এক চমু পৰিচয়$t$, $t$অসমৰ ৰাজধানী, আয়তন, জিলা, আসন আৰু জনসংখ্যা এক ঠাইতে।$t$, 'draft', $t$Assam at a Glance 2025, Directorate of Economics and Statistics, Government of Assam: https://des.assam.gov.in/sites/default/files/swf_utility_folder/departments/ecostat_medhassu_in_oid_3/this_comm/assam_at_a_glance_-_2025.pdf
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসম উত্তৰ-পূব ভাৰতৰ এখন ৰাজ্য। ইয়াৰ ৰাজধানী {{term:dispur|দিশপুৰ}}, যি গুৱাহাটীৰে এটা অংশ। অসমৰ আয়তন ৭৮,৪৩৮ বৰ্গ কিলোমিটাৰ।$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
