insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$গ্ৰাম্য স্থানীয় স্বায়ত্তশাসনৰ বাবে ২৭ খন জিলা পৰিষদ, ১৮৩ খন আঞ্চলিক পঞ্চায়ত আৰু ২,১৭০ খন গাঁও পঞ্চায়ত আছে।$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
