insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 7, 'paragraph', 'normal', $t$শেষবাৰ সম্পূৰ্ণ হোৱা {{term:census|লোকপিয়ল}} ২০১১ চনত হৈছিল। অসমৰ মূল তথ্যসমূহ এনেধৰণৰ:$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 8, 'list', 'normal', $t$মুঠ জনসংখ্যা: ৩,১২,০৫,৫৭৬ (পুৰুষ ১,৫৯,৩৯,৪৪৩; মহিলা ১,৫২,৬৬,১৩৩)
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 9, 'paragraph', 'normal', $t$২০১১ চনত ভাৰতৰ মুঠ জনসংখ্যাৰ ২.৫৮ শতাংশ অসমত আছিল।$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 10, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: আয়তন ৭৮,৪৩৮ বৰ্গ কিমি, ৩৫ খন জিলা, বিধানসভাৰ ১২৬ টা আসন, লোকসভাৰ ১৪ টা আসন, লিংগ অনুপাত ৯৫৮ আৰু সাক্ষৰতাৰ হাৰ ৭২.১৯% (লোকপিয়ল ২০১১)।$t$ from public.content where slug = $t$assam-at-a-glance$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$name-of-assam$t$, 'gk_chapter', id, 2 from public.categories where slug = $t$introduction$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$The name "Assam": where it comes from$t$, $t$How the land got the name Assam, and its older names Kamarupa and Pragjyotisha.$t$, 'draft', $t$Assam, Wikipedia (history section): https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Historians are not fully sure where the name Assam comes from. The name was first used by the British in the {{term:treaty-of-yandabo|Treaty of Yandabo}} in 1826.$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 2, 'paragraph', 'normal', $t$Most historians link the name with the {{term:ahom|Ahom}} people, who ruled much of the Brahmaputra Valley for about six hundred years. Their kingdom came to be called Assam; the Mughals wrote it as "Asham".$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 3, 'paragraph', 'normal', $t$Another popular explanation links the name to the Sanskrit word "asama", meaning unequalled or without equal. This is a view, not a settled fact.$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 4, 'heading', 'normal', $t$Older names of the land$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 5, 'paragraph', 'normal', $t$From the classical period up to the 12th century, the region was called {{term:kamarupa|Kamarupa}}, and also {{term:pragjyotisha|Pragjyotisha}}. The name Kamarupa lives on today in the districts of Kamrup and Kamrup Metropolitan.$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p5', 6, 'paragraph', 'normal', $t$Even earlier, in the 2nd century, the Greek geographer Ptolemy called the region "Kirrhadia", probably after the Kirata people.$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: the name Assam first appears in the Treaty of Yandabo (1826). Ancient names: Kamarupa and Pragjyotisha.$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$'অসম' নামৰ উৎপত্তি$t$, $t$এই ভূমিয়ে কেনেকৈ 'অসম' নাম পালে, আৰু ইয়াৰ পুৰণি নাম কামৰূপ আৰু প্ৰাগজ্যোতিষ।$t$, 'draft', $t$Assam, Wikipedia (history section): https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$'অসম' নামটো ক'ৰ পৰা আহিল, সেই বিষয়ে ইতিহাসবিদসকল সম্পূৰ্ণ নিশ্চিত নহয়। ব্ৰিটিছসকলে ১৮২৬ চনৰ {{term:treaty-of-yandabo|ইয়াণ্ডাবুৰ সন্ধিত}} প্ৰথমবাৰৰ বাবে এই নাম ব্যৱহাৰ কৰিছিল।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 2, 'paragraph', 'normal', $t$বেছিভাগ ইতিহাসবিদে এই নামটো {{term:ahom|আহোমসকলৰ}} সৈতে সংযোগ কৰে, যিসকলে প্ৰায় ছশ বছৰ ধৰি ব্ৰহ্মপুত্ৰ উপত্যকাৰ বেছিভাগ অঞ্চল শাসন কৰিছিল। তেওঁলোকৰ ৰাজ্যখনক অসম বুলি কোৱা হ'ল; মোগলসকলে ইয়াক 'আছাম' বুলি লিখিছিল।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 3, 'paragraph', 'normal', $t$আন এটা জনপ্ৰিয় ব্যাখ্যা অনুসৰি নামটো সংস্কৃত শব্দ 'অসম'ৰ পৰা আহিছে, যাৰ অৰ্থ যাৰ সমান নাই বা অতুলনীয়। এইটো এটা মত হে, প্ৰমাণিত তথ্য নহয়।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'h1', 4, 'heading', 'normal', $t$এই ভূমিৰ পুৰণি নামসমূহ$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 5, 'paragraph', 'normal', $t$ধ্ৰুপদী যুগৰ পৰা দ্বাদশ শতিকালৈ এই অঞ্চলক {{term:kamarupa|কামৰূপ}} আৰু {{term:pragjyotisha|প্ৰাগজ্যোতিষ}} বুলি কোৱা হৈছিল। কামৰূপ নামটো আজিও কামৰূপ আৰু কামৰূপ মহানগৰ জিলাৰ নামত জীয়াই আছে।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p5', 6, 'paragraph', 'normal', $t$তাতোকৈও আগতে, খ্ৰীষ্টীয় দ্বিতীয় শতিকাত গ্ৰীক ভূগোলবিদ টলেমীয়ে এই অঞ্চলক 'কিৰ্হাডিয়া' বুলি উল্লেখ কৰিছিল, সম্ভৱতঃ কিৰাত জনগোষ্ঠীৰ নামেৰে।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: 'অসম' নামটো প্ৰথমে ইয়াণ্ডাবুৰ সন্ধিত (১৮২৬) পোৱা যায়। প্ৰাচীন নাম: কামৰূপ আৰু প্ৰাগজ্যোতিষ।$t$ from public.content where slug = $t$name-of-assam$t$ on conflict do nothing;
insert into public.content (slug, kind, category_id, position) select $t$state-symbols-of-assam$t$, 'gk_chapter', id, 3 from public.categories where slug = $t$introduction$t$ on conflict (slug) do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$State symbols of Assam$t$, $t$The official animal, bird, tree, flower, song and other symbols of Assam.$t$, 'draft', $t$Symbols of Assam, Government of Assam: https://assam.gov.in/node/389 ; Raj Bhavan Assam: https://rajbhavan.assam.gov.in/about-us/symbols-assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Like every Indian state, Assam has official symbols that stand for its nature and culture. These are the symbols listed by the Government of Assam:$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 2, 'list', 'verified_fact', $t$State animal: {{term:one-horned-rhinoceros|One-horned rhinoceros}} (Gor)
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 3, 'paragraph', 'normal', $t$The state song "O Mur Apunar Desh" was written by Lakshminath Bezbaroa, one of the greatest writers of Assamese literature.$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 4, 'paragraph', 'normal', $t$The state's literary society is the Asam Sahitya Sabha.$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Common exam question: state bird = White-winged wood duck (Deohanh); state flower = Foxtail orchid (Kopou phul); state tree = Hollong.$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ ৰাজ্যিক প্ৰতীকসমূহ$t$, $t$অসমৰ চৰকাৰী জন্তু, পক্ষী, বৃক্ষ, ফুল, গীত আৰু অন্যান্য প্ৰতীক।$t$, 'draft', $t$Symbols of Assam, Government of Assam: https://assam.gov.in/node/389 ; Raj Bhavan Assam: https://rajbhavan.assam.gov.in/about-us/symbols-assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ভাৰতৰ আন ৰাজ্যৰ দৰে অসমৰো প্ৰকৃতি আৰু সংস্কৃতিক প্ৰতিনিধিত্ব কৰা চৰকাৰী প্ৰতীক আছে। অসম চৰকাৰে উল্লেখ কৰা প্ৰতীকসমূহ এনেধৰণৰ:$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 2, 'list', 'verified_fact', $t$ৰাজ্যিক জন্তু: {{term:one-horned-rhinoceros|এশিঙীয়া গঁড়}}
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 3, 'paragraph', 'normal', $t$ৰাজ্যিক সংগীত 'অ' মোৰ আপোনাৰ দেশ' অসমীয়া সাহিত্যৰ অন্যতম শ্ৰেষ্ঠ সাহিত্যিক লক্ষ্মীনাথ বেজবৰুৱাই ৰচনা কৰিছিল।$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 4, 'paragraph', 'normal', $t$ৰাজ্যখনৰ সাহিত্য সভা হৈছে অসম সাহিত্য সভা।$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 5, 'fact_box', 'exam_fact', $t$পৰীক্ষাত সঘনাই সোধা প্ৰশ্ন: ৰাজ্যিক পক্ষী = দেওহাঁহ; ৰাজ্যিক ফুল = কপৌ ফুল; ৰাজ্যিক বৃক্ষ = হোলোং।$t$ from public.content where slug = $t$state-symbols-of-assam$t$ on conflict do nothing;
