insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$Location, boundaries and neighbours$t$, $t$Where Assam lies on the map, and which countries and states border it.$t$, 'draft', $t$State Profile, Office of the Chief Minister of Assam: https://cm.assam.gov.in/state-profile
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$Assam lies in Northeast India, roughly between 24° and 28° North latitude and between 90° and 96° East longitude.$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Neighbours on every side$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 3, 'list', 'geography', $t$North: Bhutan and Arunachal Pradesh
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$Assam shares an {{term:international-border|international border}} with two countries, Bhutan and Bangladesh, and borders seven Indian states. It touches every other Northeast state except Sikkim.$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p3', 5, 'paragraph', 'normal', $t$Assam and the rest of Northeast India are joined to the rest of the country by the {{term:siliguri-corridor|Siliguri Corridor}}, a narrow strip of land in West Bengal.$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p4', 6, 'paragraph', 'normal', $t$Three of India's six physical divisions are found in Assam: the Eastern Hills (part of the Himalayan system), the Brahmaputra plain (part of the Northern Plains), and the Karbi Anglong hills (part of the Deccan Plateau).$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 7, 'fact_box', 'exam_fact', $t$Remember for exams: 2 neighbouring countries (Bhutan, Bangladesh) and 7 neighbouring states.$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$অসমৰ অৱস্থান, সীমা আৰু চুবুৰীয়া$t$, $t$মানচিত্ৰত অসম ক'ত আছে, আৰু কোনবোৰ দেশ আৰু ৰাজ্যৰ সৈতে ইয়াৰ সীমা আছে।$t$, 'draft', $t$State Profile, Office of the Chief Minister of Assam: https://cm.assam.gov.in/state-profile
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$অসম উত্তৰ-পূব ভাৰতত, প্ৰায় ২৪° ৰ পৰা ২৮° উত্তৰ অক্ষাংশ আৰু ৯০° ৰ পৰা ৯৬° পূব দ্ৰাঘিমাংশৰ মাজত অৱস্থিত।$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
