insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'l1', 3, 'list', 'geography', $t$উত্তৰে: ভূটান আৰু অৰুণাচল প্ৰদেশ
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$অসমৰ দুখন দেশৰ সৈতে {{term:international-border|আন্তঃৰাষ্ট্ৰীয় সীমা}} আছে, ভূটান আৰু বাংলাদেশ, আৰু ভাৰতৰ সাতখন ৰাজ্যৰ সৈতে সীমা আছে। ছিকিমৰ বাহিৰে উত্তৰ-পূবৰ আন সকলো ৰাজ্যৰ সৈতে অসমৰ সীমা লাগি আছে।$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p3', 5, 'paragraph', 'normal', $t$পশ্চিমবংগৰ এক ঠেক ভূখণ্ড {{term:siliguri-corridor|শিলিগুৰি কৰিডৰৰ}} জৰিয়তে অসম আৰু উত্তৰ-পূব ভাৰত দেশৰ বাকী অংশৰ সৈতে সংযুক্ত হৈ আছে।$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p4', 6, 'paragraph', 'normal', $t$ভাৰতৰ ছটা প্ৰাকৃতিক বিভাগৰ তিনিটা অসমত পোৱা যায়: পূবৰ পাহাৰীয়া অঞ্চল (হিমালয় প্ৰণালীৰ অংশ), ব্ৰহ্মপুত্ৰৰ সমভূমি (উত্তৰৰ সমভূমিৰ অংশ), আৰু কাৰ্বি আংলঙৰ পাহাৰ (দাক্ষিণাত্য মালভূমিৰ অংশ)।$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'exam1', 7, 'fact_box', 'exam_fact', $t$পৰীক্ষাৰ বাবে মনত ৰাখক: ২ খন চুবুৰীয়া দেশ (ভূটান, বাংলাদেশ) আৰু ৭ খন চুবুৰীয়া ৰাজ্য।$t$ from public.content where slug = $t$location-and-boundaries$t$ on conflict do nothing;
