insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'en', $t$How the present state was formed$t$, $t$From the Treaty of Yandabo in 1826 to the new states carved out of Assam.$t$, 'draft', $t$Assam, Wikipedia (history section): https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p1', 1, 'paragraph', 'normal', $t$The Burmese occupied Assam in the early 19th century. The {{term:treaty-of-yandabo|Treaty of Yandabo}} of 1826 ended this, and the British East India Company took control of Assam. Over the following years the British took over the whole region.$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'h1', 2, 'heading', 'normal', $t$Timeline$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'l1', 3, 'list', 'event', $t$1826: Treaty of Yandabo; Assam comes under British control.
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'p2', 4, 'paragraph', 'normal', $t$So the four states of Nagaland, Meghalaya, Mizoram and Arunachal Pradesh were all once part of Assam.$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'en', 'exam1', 5, 'fact_box', 'exam_fact', $t$Remember for exams: 1874 separate province; 1963 Nagaland; 1972 Meghalaya; 1987 Mizoram and Arunachal Pradesh.$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
insert into public.content_versions (content_id, lang, title, summary, status, sources, last_checked) select id, 'as', $t$বৰ্তমানৰ অসম ৰাজ্য কেনেকৈ গঠন হ'ল$t$, $t$১৮২৬ চনৰ ইয়াণ্ডাবুৰ সন্ধিৰ পৰা অসমৰ পৰা নতুন ৰাজ্য গঠনলৈ।$t$, 'draft', $t$Assam, Wikipedia (history section): https://en.wikipedia.org/wiki/Assam
insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p1', 1, 'paragraph', 'normal', $t$ঊনবিংশ শতিকাৰ আৰম্ভণিতে মানে (বৰ্মীসকলে) অসম অধিকাৰ কৰিছিল। ১৮২৬ চনৰ {{term:treaty-of-yandabo|ইয়াণ্ডাবুৰ সন্ধিয়ে}} ইয়াৰ অন্ত পেলায় আৰু ব্ৰিটিছ ইষ্ট ইণ্ডিয়া কোম্পানীয়ে অসমৰ শাসনভাৰ লয়। পৰৱৰ্তী বছৰবোৰত ব্ৰিটিছে গোটেই অঞ্চলটো দখল কৰে।$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
