insert into public.content_blocks (content_id, lang, block_key, position, block_type, style, body) select id, 'as', 'p2', 4, 'paragraph', 'normal', $t$এইদৰে নাগালেণ্ড, মেঘালয়, মিজোৰাম আৰু অৰুণাচল প্ৰদেশ, এই চাৰিখন ৰাজ্য এসময়ত অসমৰে অংশ আছিল।$t$ from public.content where slug = $t$formation-of-assam$t$ on conflict do nothing;
